const b = $json.body || $json;
const { report_id, action, reviewer, edited_fields } = b;
if (!report_id) throw new Error('report_id required');
if (!['approve','reject','edit'].includes(action)) throw new Error(`Invalid action: ${action}`);
if (!reviewer) throw new Error('reviewer required');
const statusMap = { approve: 'approved', reject: 'rejected', edit: 'pending_approval' };
return [{ json: {
  report_id,
  action,
  reviewer,
  new_status: statusMap[action],
  edited_fields: edited_fields || null,
  audit_entry: JSON.stringify({ timestamp: new Date().toISOString(), reviewer, action, changes: edited_fields || null })
} }];
